1	import express from 'express';
2	import cors from 'cors';
3	import { fileURLToPath } from 'url';
4	import { dirname, join } from 'path';
5	import {
6	  createCollection,
7	  getCollection,
8	  listCollections,
9	  deleteCollection,
10	  upsertDocuments,
11	  hybridSearch,
12	  upsertReviewProgress,
13	  updateMastery,
14	  getWeakPoints,
15	  getAllProgress,
16	} from './seekdb.mjs';
17	
18	const __filename = fileURLToPath(import.meta.url);
19	const __dirname = dirname(__filename);
20	
21	const app = express();
22	const PORT = 8787;
23	
24	app.use(cors());
25	app.use(express.json({ limit: '50mb' }));
26	app.use('/models', express.static(join(__dirname, '..', 'models')));
27	
28	app.get('/api/health', (_req, res) => {
29	  res.json({ status: 'ok' });
30	});
31	
32	app.post('/api/collections', async (req, res) => {
33	  try {
34	    const { courseId } = req.body;
35	    if (!courseId || typeof courseId !== 'string') {
36	      return res.status(400).json({ error: '缺少 courseId' });
37	    }
38	    await createCollection(courseId);
39	    res.json({ ok: true, courseId });
40	  } catch (e) {
41	    res.status(500).json({ error: e.message });
42	  }
43	});
44	
45	app.get('/api/collections', async (_req, res) => {
46	  try {
47	    const list = await listCollections();
48	    const result = [];
49	    for (const col of list) {
50	      const name = col.name || col;
51	      let chunkCount = 0;
52	      try { chunkCount = await col.count(); } catch { /* empty */ }
53	      result.push({
54	        courseId: name,
55	        collectionId: col.collectionId || name,
56	        docCount: chunkCount,
57	        chunkCount,
58	        dimension: col.dimension || 512,
59	      });
60	    }
61	    res.json(result);
62	  } catch (e) {
63	    res.status(500).json({ error: e.message });
64	  }
65	});
66	
67	app.delete('/api/collections/:courseId', async (req, res) => {
68	  try {
69	    await deleteCollection(req.params.courseId);
70	    res.json({ ok: true });
71	  } catch (e) {
72	    res.status(500).json({ error: e.message });
73	  }
74	});
75	
76	app.post('/api/import', async (req, res) => {
77	  try {
78	    const { courseId, chunks } = req.body;
79	    if (!courseId || !Array.isArray(chunks)) {
80	      return res.status(400).json({ error: '缺少 courseId 或 chunks' });
81	    }
82	    if (chunks.length === 0) {
83	      return res.json({ ok: true, imported: 0 });
84	    }
85	    const docs = chunks.map((c) => ({
86	      id: c.id,
87	      text: c.text,
88	      embedding: c.embedding,
89	      file_name: c.fileName || '',
90	      chunk_index: c.chunkIndex ?? 0,
91	    }));
92	    await upsertDocuments(courseId, docs);
93	    res.json({ ok: true, imported: docs.length });
94	  } catch (e) {
95	    res.status(500).json({ error: e.message });
96	  }
97	});
98	
99	app.post('/api/search', async (req, res) => {
100	  try {
101	    const { courseId, query, vector, topK } = req.body;
102	    if (!courseId || !query || !vector) {
103	      return res.status(400).json({ error: '缺少 courseId / query / vector' });
104	    }
105	    const rawResults = await hybridSearch(courseId, query, vector, topK || 10);
106	    const results = (Array.isArray(rawResults) ? rawResults : []).map((row) => {
107	      let meta = row.metadata ?? row.METADATA ?? {};
108	      if (typeof meta === 'string') {
109	        try { meta = JSON.parse(meta); } catch { meta = {}; }
110	      }
111	      return {
112	        id: String(row._id ?? row.id ?? ''),
113	        text: String(row.document ?? row.DOCUMENT ?? row.text ?? ''),
114	        score: Number(row._score ?? row._distance ?? row.score ?? 0),
115	        file_name: meta.file_name || '',
116	        chunk_index: meta.chunk_index ?? 0,
117	      };
118	    });
119	    res.json({ results });
120	  } catch (e) {
121	    res.status(500).json({ error: e.message });
122	  }
123	});
124	
125	app.post('/api/review/add', async (req, res) => {
126	  try {
127	    const { courseId, chunkId, text, fileName } = req.body;
128	    if (!courseId || !chunkId) {
129	      return res.status(400).json({ error: '缺少 courseId 或 chunkId' });
130	    }
131	    await upsertReviewProgress({
132	      id: `${courseId}::${chunkId}`,
133	      collection_id: courseId,
134	      chunk_id: chunkId,
135	      text,
136	      file_name: fileName,
137	    });
138	    res.json({ ok: true });
139	  } catch (e) {
140	    res.status(500).json({ error: e.message });
141	  }
142	});
143	
144	app.post('/api/review/mastery', async (req, res) => {
145	  try {
146	    const { id, mastery } = req.body;
147	    if (!id || mastery === undefined) {
148	      return res.status(400).json({ error: '缺少 id 或 mastery' });
149	    }
150	    await updateMastery(id, mastery);
151	    res.json({ ok: true });
152	  } catch (e) {
153	    res.status(500).json({ error: e.message });
154	  }
155	});
156	
157	app.get('/api/review/weak/:courseId', async (req, res) => {
158	  try {
159	    const rows = await getWeakPoints(req.params.courseId, 5);
160	    res.json(rows);
161	  } catch (e) {
162	    res.status(500).json({ error: e.message });
163	  }
164	});
165	
166	app.get('/api/review/all/:courseId', async (req, res) => {
167	  try {
168	    const rows = await getAllProgress(req.params.courseId);
169	    res.json(rows);
170	  } catch (e) {
171	    res.status(500).json({ error: e.message });
172	  }
173	});
174	
175	app.listen(PORT, () => {
176	  console.log(`StudyStack API server running on http://localhost:${PORT}`);
177	});
