import { pipeline, env } from '@xenova/transformers';

env.allowLocalModels = true;
env.localModelPath = '/models/';
env.allowRemoteModels = true;

let embedder: any = null;

async function getModel() {
  if (!embedder) {
    try {
      embedder = await pipeline(
        'feature-extraction',
        'Xenova/bge-small-zh-v1.5',
        { dtype: 'q8', device: 'webgpu' } as any
      );
    } catch {
      embedder = await pipeline(
        'feature-extraction',
        'Xenova/bge-small-zh-v1.5',
        { dtype: 'q8', device: 'wasm' } as any
      );
    }
  }
  return embedder;
}

self.onmessage = async (e: MessageEvent) => {
  const { id, type, texts } = e.data;
  try {
    if (type === 'embed') {
      const model = await getModel();
      const results: number[][] = [];
      for (const text of texts) {
        const output = await model(text, { pooling: 'cls' } as any);
        const arr = output?.data ?? output?.tolist?.() ?? Array.from(output);
        results.push(Array.isArray(arr) ? arr : Array.from(arr as Iterable<number>));
      }
      (self as unknown as Worker).postMessage({ id, results });
    } else if (type === 'ready') {
      await getModel();
      (self as unknown as Worker).postMessage({ id, ready: true });
    }
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    (self as unknown as Worker).postMessage({ id, error: message });
  }
};

