268	function splitIntoChunks(text: string, size: number, overlap: number): string[] {
269	  const sentences = text.match(/[^。！？.!?\n]+[。！？.!?\n]?/g) || [text];
270	  const chunks: string[] = [];
271	  let current = '';
272	  for (const sentence of sentences) {
273	    if (current.length + sentence.length > size && current.length > 0) {
274	      chunks.push(current.trim());
275	      const words = current.split(/\s+/);
276	      let keep = '';
277	      let keepLen = 0;
278	      for (let i = words.length - 1; i >= 0; i--) {
279	        if (keepLen + words[i].length > overlap) break;
280	        keep = words[i] + ' ' + keep;
281	        keepLen += words[i].length + 1;
282	      }
283	      current = keep.trim() + sentence;
284	    } else {
285	      current += sentence;
286	    }
287	  }
288	  if (current.trim()) chunks.push(current.trim());
289	  return chunks;
290	}
291	
292	interface ParsedFile {
293	  fileName: string;
294	  chunks: Array<{ id: string; text: string; fileName: string; chunkIndex: number }>;
295	}
296	
297	function parseFile(fileName: string, content: string, chunkSize: number, chunkOverlap: number): ParsedFile {
298	  const chunks: ParsedFile['chunks'] = [];
299	  if (fileName.endsWith('.json')) {
300	    try {
301	      const arr = JSON.parse(content);
302	      if (Array.isArray(arr)) {
303	        arr.forEach((item: { id?: string; title?: string; text?: string }, idx: number) => {
304	          const text = item.text || item.title || '';
305	          if (!text) return;
306	          const subChunks = splitIntoChunks(text, chunkSize, chunkOverlap);
307	          subChunks.forEach((c, ci) => {
308	            chunks.push({
309	              id: `${item.id || idx}_${ci}`,
310	              text: c,
311	              fileName: item.title || fileName,
312	              chunkIndex: ci,
313	            });
314	          });
315	        });
316	      }
317	    } catch {
318	      const textChunks = splitIntoChunks(content, chunkSize, chunkOverlap);
319	      textChunks.forEach((c, i) => {
320	        chunks.push({ id: `${fileName}_${i}`, text: c, fileName, chunkIndex: i });
321	      });
322	    }
323	  } else {
324	    const textChunks = splitIntoChunks(content, chunkSize, chunkOverlap);
325	    textChunks.forEach((c, i) => {
326	      chunks.push({ id: `${fileName}_${i}`, text: c, fileName, chunkIndex: i });
327	    });
328	  }
329	  return { fileName, chunks };
330	}
331	
332	async function handleImport() {
333	  if (!state.currentCourse) { showToast('请先选择课程', 'error'); return; }
334	  if (!state.modelReady) { showToast('模型尚未加载完成', 'error'); return; }
335	
336	  const fileInput = document.getElementById('file-input') as HTMLInputElement;
337	  const files = fileInput?.files;
338	  if (!files || files.length === 0) { showToast('请选择文件', 'error'); return; }
339	
340	  const chunkSize = parseInt((document.getElementById('chunk-size') as HTMLInputElement)?.value || '300');
341	  const chunkOverlap = parseInt((document.getElementById('chunk-overlap') as HTMLInputElement)?.value || '50');
342	
343	  const progressArea = document.getElementById('import-progress-area');
344	  const statusText = document.getElementById('import-status-text');
345	  const progressFill = document.getElementById('import-progress-fill');
346	  const fileListEl = document.getElementById('import-file-list');
347	  if (progressArea) progressArea.style.display = 'block';
348	  if (fileListEl) clearChildren(fileListEl);
349	
350	  try {
351	    const allParsed: ParsedFile[] = [];
352	    for (const file of Array.from(files)) {
353	      const content = await file.text();
354	      const parsed = parseFile(file.name, content, chunkSize, chunkOverlap);
355	      allParsed.push(parsed);
356	      if (fileListEl) {
357	        const item = el('div', { className: 'file-item' }, `${file.name} — ${parsed.chunks.length} 个分块`);
358	        fileListEl.appendChild(item);
359	      }
360	    }
361	
362	    const totalChunks = allParsed.reduce((sum, p) => sum + p.chunks.length, 0);
363	    if (totalChunks === 0) { showToast('未解析到任何内容', 'error'); return; }
364	
365	    if (statusText) statusText.textContent = `正在向量化 0/${totalChunks}...`;
366	    if (progressFill) progressFill.style.width = '0%';
367	
368	    const allChunks = allParsed.flatMap((p) => p.chunks);
369	    const batchSize = 16;
370	    const embedded: Array<typeof allChunks[0] & { embedding: number[] }> = [];
371	
372	    for (let i = 0; i < allChunks.length; i += batchSize) {
373	      const batch = allChunks.slice(i, i + batchSize);
374	      const texts = batch.map((c) => c.text);
375	      const vectors = await embedTexts(texts);
376	      batch.forEach((c, j) => {
377	        embedded.push({ ...c, embedding: vectors[j] });
378	      });
379	      const done = Math.min(i + batchSize, totalChunks);
380	      if (statusText) statusText.textContent = `正在向量化 ${done}/${totalChunks}...`;
381	      if (progressFill) progressFill.style.width = `${(done / totalChunks) * 80}%`;
382	    }
383	
384	    if (statusText) statusText.textContent = '正在写入 seekdb...';
385	    if (progressFill) progressFill.style.width = '85%';
386	
387	    const importBatchSize = 50;
388	    for (let i = 0; i < embedded.length; i += importBatchSize) {
389	      const batch = embedded.slice(i, i + importBatchSize);
390	      await api.importChunks(
391	        state.currentCourse,
392	        batch.map((c) => ({
393	          id: c.id,
394	          text: c.text,
395	          embedding: c.embedding,
396	          fileName: c.fileName,
397	          chunkIndex: c.chunkIndex,
398	        }))
399	      );
400	      const done = Math.min(i + importBatchSize, embedded.length);
401	      if (progressFill) progressFill.style.width = `${85 + (done / embedded.length) * 15}%`;
402	    }
403	
404	    if (statusText) statusText.textContent = `导入完成: ${embedded.length} 个分块`;
405	    if (progressFill) progressFill.style.width = '100%';
406	    showToast(`成功导入 ${embedded.length} 个分块`, 'success');
407	    refreshCollections();
408	  } catch (e) {
409	    const msg = e instanceof Error ? e.message : String(e);
410	    showToast(`导入失败: ${msg}`, 'error');
411	    if (statusText) statusText.textContent = `导入失败: ${msg}`;
412	  }
413	}
414	
