416	
417	function renderSearch() {
418	  const container = document.getElementById('tab-search');
419	  if (!container) return;
420	  clearChildren(container);
421	
422	  const card = el('div', { className: 'card' });
423	  card.appendChild(el('h3', {}, '混合检索'));
